load_nih_data <- function(data_type = c("awards", "publications"), 
                          consortia = NULL, 
                          date = NULL) {
  
  data_type <- match.arg(data_type)
  data_dir <- file.path(project_root, "data", data_type)
  
  # Build file pattern based on naming convention
  if (!is.null(consortia) && !is.null(date)) {
    pattern <- paste0("NIHReporter-", consortia, "-", data_type, "-", date, "\\.csv$")
  } else if (!is.null(consortia)) {
    pattern <- paste0("NIHReporter-", consortia, "-", data_type, "-.*\\.csv$")
  } else {
    pattern <- paste0("NIHReporter-.*-", data_type, "-.*\\.csv$")
  }
  
  # Find matching files
  files <- list.files(data_dir, pattern = pattern, full.names = TRUE)
  
  if (length(files) == 0) {
    stop("No files found matching pattern: ", pattern, " in ", data_dir)
  }
  
  # If multiple files, use most recent
  if (length(files) > 1 && is.null(date)) {
    dates <- str_extract(basename(files), "\\d{8}")
    files <- files[which.max(as.Date(dates, format = "%Y%m%d"))]
    cat("Multiple files found. Using most recent:", basename(files), "\n")
  }

  # Load file(s)
  if(data_type=="awards") {
    data_list <- lapply(files, function(f) {
      # Extract consortia from filename format
      consortia_id <- str_match(basename(f), "NIHReporter-(.*?)-(awards|publications)")[, 2]
      
      cat("Loading:", basename(f), "\n")
      
      # Use suppressWarnings to avoid vroom parsing warnings
      df <- suppressWarnings({
        read.csv(f, 
              header = TRUE,
              stringsAsFactors = FALSE,
              colClasses = c(Serial.Number = "character"))
      })
      
      # Remove columns with no name or auto-generated names
      valid_cols <- !grepl("^V\\d+$|^$", names(df))
      df <- df[, valid_cols]
      
      df$consortia <- consortia_id
      df$source_file <- basename(f)
      
      return(as_tibble(df))
    })
    
    
  } else {
    data_list <- lapply(files, function(f) {
      # Extract project_id from filename format
      consortia_id <- str_match(basename(f), "NIHReporter-(.*?)-(awards|publications)")[, 2]
      
      cat("Loading:", basename(f), "\n")
      
      # Use suppressWarnings to avoid vroom parsing warnings
      df <- suppressWarnings({
        read.csv(f, 
                 header = TRUE,
                 stringsAsFactors = FALSE)
      })
      
      # Remove columns with no name or auto-generated names
      valid_cols <- !grepl("^V\\d+$|^$", names(df))
      df <- df[, valid_cols]
      
      df$consortia <- consortia_id
      df$source_file <- basename(f)
      
      return(as_tibble(df))
    })
  }

  data <- bind_rows(data_list)
  cat("Loaded", nrow(data), "rows for", n_distinct(data$consortia), "project(s)\n")
  
  return(data)
}

# Load all consortia data of a given type
load_all_consortia <- function(data_type = c("awards", "publications")) {
  data_type <- match.arg(data_type)
  data_dir <- file.path(project_root, "data", data_type)
  
  pattern <- paste0("NIHReporter-.*-", data_type, "-.*\\.csv$")
  files <- list.files(data_dir, pattern = pattern, full.names = TRUE)
  
  if (length(files) == 0) {
    stop("No ", data_type, " files found in ", data_dir)
  }
  
  # Extract unique consortia IDs from filename format
  consortia <- unique(str_match(basename(files), "NIHReporter-(.*?)-(awards|publications)")[, 2])
  
  # Load most recent file for each project
  result <- lapply(consortia, function(pid) {
    load_nih_data(data_type, consortia = pid)
  })
  names(result) <- consortia
  
  return(result)
}

# Function to save processed data
save_processed_data <- function(data, filename, format = "csv") {
  output_path <- file.path(project_root, "data", "processed", filename)
  
  if (format == "csv") {
    write_csv(data, output_path)
  } else if (format == "xlsx") {
    write_xlsx(data, output_path)
  } else if (format == "rds") {
    saveRDS(data, output_path)
  }
  
  cat("Saved", nrow(data), "rows to", filename, "\n")
}

# Function to generate data quality report
generate_quality_report <- function(data, dataset_name) {
  cat("\n==== Data Quality Report:", dataset_name, "====\n\n")
  
  cat("Dimensions:", nrow(data), "rows x", ncol(data), "columns\n\n")
  
  cat("Missing Data Summary:\n")
  missing_summary <- data %>%
    summarise(across(everything(), ~sum(is.na(.)))) %>%
    pivot_longer(everything(), names_to = "variable", values_to = "missing_count") %>%
    mutate(missing_pct = round(missing_count / nrow(data) * 100, 2)) %>%
    filter(missing_count > 0) %>%
    arrange(desc(missing_pct))
  
  print(missing_summary)
  
  cat("\n")
  print(skim(data))
  
  return(invisible(missing_summary))
}

